    }

    override fun lift(value: Long): RelayRemoteSettingsClient {
        return RelayRemoteSettingsClient(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): RelayRemoteSettingsClient {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: RelayRemoteSettingsClient) = 8UL

    override fun write(value: RelayRemoteSettingsClient, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



