sealed class RelayApiException: kotlin.Exception() {
    
    class Network(
        
        val `reason`: kotlin.String
        ) : RelayApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Api(
        
        val `status`: kotlin.UShort, 
        
        val `code`: kotlin.String, 
        
        val `detail`: kotlin.String
        ) : RelayApiException() {
        override val message
            get() = "status=${ `status` }, code=${ `code` }, detail=${ `detail` }"
    }
    
    class Other(
        
        val `reason`: kotlin.String
        ) : RelayApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<RelayApiException> {
        override fun lift(error_buf: RustBuffer.ByValue): RelayApiException = FfiConverterTypeRelayApiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeRelayApiError : FfiConverterRustBuffer<RelayApiException> {
    override fun read(buf: ByteBuffer): RelayApiException {
        

        return when(buf.getInt()) {
            1 -> RelayApiException.Network(
                FfiConverterString.read(buf),
                )
            2 -> RelayApiException.Api(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> RelayApiException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RelayApiException): ULong {
        return when(value) {
            is RelayApiException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is RelayApiException.Api -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`status`)
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is RelayApiException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: RelayApiException, buf: ByteBuffer) {
        when(value) {
            is RelayApiException.Network -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is RelayApiException.Api -> {
                buf.putInt(2)
                FfiConverterUShort.write(value.`status`, buf)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is RelayApiException.Other -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalBoolean: FfiConverterRustBuffer<kotlin.Boolean?> {
    override fun read(buf: ByteBuffer): kotlin.Boolean? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterBoolean.read(buf)
    }

    override fun allocationSize(value: kotlin.Boolean?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterBoolean.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Boolean?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterBoolean.write(value, buf)
        }
    }
}




