/**
 * @suppress
 */
public object FfiConverterSequenceTypeRelayAddress: FfiConverterRustBuffer<List<RelayAddress>> {
    override fun read(buf: ByteBuffer): List<RelayAddress> {
        val len = buf.getInt()
        return List<RelayAddress>(len) {
            FfiConverterTypeRelayAddress.read(buf)
        }
    }

    override fun allocationSize(value: List<RelayAddress>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeRelayAddress.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<RelayAddress>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeRelayAddress.write(it, buf)
        }
    }
}



